def route(src,dst,tmin,tmax,gap=600,tend=100000):
    # earliest arrival style: state = node -> earliest time reachable
    best={}
    starts=[]
    for u,v,t in events:
        if tmin<=t<=tmax and (u==src or v==src):
            other=v if u==src else u
            starts.append((other,t,(src,other,t)))
    paths={}
    for o,t,e in starts:
        if o not in best or t<best[o]:
            best[o]=t; paths[o]=[e]
    if src not in best: best[src]=tmin
    changed=True
    # process events in time order repeatedly
    for _ in range(3):
        for u,v,t in events:
            for a,b in ((u,v),(v,u)):
                if a in best and best[a]<=t<=best[a]+gap and t<=tend:
                    if b not in best or t<best[b]:
                        best[b]=t; paths[b]=paths.get(a,[])+[(a,b,t)]
    return best.get(dst), paths.get(dst)

